const body = $input.item.json.body || $input.item.json;
const firstName = body.first_name || (body.name ? body.name.split(' ')[0] : '');
const lastName = body.last_name || (body.name && body.name.split(' ').length > 1 ? body.name.split(' ').slice(1).join(' ') : '');
const email = body.email || '';
const company = body.company_name || body.company || '';
const jobTitle = body.job_title || body.title || '';
const linkedinUrl = body.linkedin_url || '';
const phone = body.phone || '';
const source = body.source || 'manual_webhook';
const domain = company ? company.toLowerCase().replace(/[^a-z0-9]/g, '') + '.com' : null;

return [{
  json: {
    first_name: firstName,
    last_name: lastName,
    email: email,
    phone: phone,
    company_name: company,
    domain: domain,
    job_title: jobTitle,
    linkedin_url: linkedinUrl,
    source: source,
    raw_payload: body
  }
}];
